  function photoEmptyHTML(look,small=false){return `<div class="reference-empty ${small?'small':''}"><span class="reference-style" translate="no">${look.style}</span><div class="reference-colors" aria-label="הפלטה המוצעת">${look.palette.map(c=>`<i style="--color:${c.hex}" title="${c.name}"></i>`).join('')}</div><strong>אין כרגע צילום נוסף תואם לכיוון.</strong><p>ההמלצה נשמרת לפי הנתונים שלך. תמונה שאינה עומדת בסינון לא מוצגת במקומה.</p></div>`;}
  function photoFigureHTML(look,{small=false}={}){return look.reference?`<img src="${look.reference.src}" width="600" height="800" alt="${escape(look.reference.alt)} — צילום להשראה, לא הדמיה" loading="lazy">`:photoEmptyHTML(look,small);}

  function matchingDetails(input){const p=normalize(input);return `<dl class="matching-facts">${profileFacts(p).map(f=>`<div class="${f.known?'':'not-selected'}"><dt>${f.label}</dt><dd>${escape(f.value)}</dd></div>`).join('')}<div><dt>אירוע</dt><dd>${EVENTS.find(e=>e[0]===p.event)[1]}</dd></div><div><dt>סגנון</dt><dd translate="no">${STYLES.find(s=>s.id===p.style).name}</dd></div></dl>`;}
  function styleExample(styleId,used=new Set()){
    const p={...profile,style:styleId},look=recommend(p,{mode:referenceMode}).find(l=>l.kind===(['bold','editorial'].includes(styleId)?'trendy':styleId==='natural'?'natural':'elegant'));
    const preferred={natural:'freckles',clean:'sleek',french:'blonde-bob',oldmoney:'blonde-waves',softglam:'silver-elegance',classic:'copper-soft',bold:'bold',editorial:'glow'}[styleId],candidates=photoCandidates(p,{mode:referenceMode});
    const photo=candidates.find(g=>g.id===preferred&&!used.has(g.id))||candidates.find(g=>!used.has(g.id));if(photo)used.add(photo.id);return {...look,reference:photo||null,referenceAudit:photo?auditPhoto(photo,p):null};
  }
  function refreshExamples(){const used=new Set();document.querySelectorAll('.style-option').forEach(button=>{const look=styleExample(button.dataset.value,used);button.querySelector('.style-visual').innerHTML=photoFigureHTML(look,{small:true});});renderGallery();if($('gallery-dialog').open)updateGalleryDialog();}

  const paths={heart:'<path d="M20 5a5 5 0 0 0-7 0l-1 1-1-1a5 5 0 0 0-7 7l8 8 8-8a5 5 0 0 0 0-7Z"/>',arrow:'<path d="M20 12H4m6-6-6 6 6 6"/>',right:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',upload:'<path d="M12 17V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',download:'<path d="M12 3v14m-5-5 5 5 5-5M4 17v4h16v-4"/>',reset:'<path d="M4 10a8 8 0 1 1 1 8M4 4v6h6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',face:'<path d="M5 9a7 7 0 0 1 14 0v5c0 5-4 8-7 8s-7-3-7-8V9ZM8 10h1m6 0h1M9 17q3 2 6 0"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>',work:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 13q9 5 18 0"/>',sparkle:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z"/>',music:'<path d="M9 18V5l12-2v13M9 8l12-2"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="16" rx="3" ry="3"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3V7Z"/><circle cx="12" cy="13" r="4"/>'};
  function icon(name){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths[name]||paths.sparkle}</svg>`;}
