    rows.push(['העיצוב לסגנון',look.hairFinish],['כיוון מתוך 2026',look.trend.he+' — '+look.trend.source.name+'; '+look.trend.note],['סינון הצילום',look.reference?'צילום להשראה. לא אומתו בתמונה: '+(look.referenceAudit.unverified.map(k=>FIELD_NAMES[k]).join(', ')||'אין שדות חסרים ביחס לבחירות'):'לא נמצא צילום העומד בסינון הנבחר.']);rows.push(['הנתונים שבחרת',profileFacts(look.profile).map(f=>f.label+': '+(f.known?f.value:'לא נבחר')).join(' · ')]);const measuredRows=rows.map(([label,text])=>[label,wrapText(ctx,text,980)]);
