  const API=Object.freeze({normalize,recommend,photoCandidates,auditPhoto,inspirationSearch,photoSource,profileFacts,trends:TRENDS,defaults:{...DEFAULTS},styles:STYLES,events:EVENTS,faces:FACES,gallery:GALLERY.map(({src,...g})=>g),drawRecommendationCard});
