  function readFavorites(){try{const data=JSON.parse(localStorage.getItem(storageKey)||'[]');return Array.isArray(data)?data.slice(0,18).filter(x=>x&&typeof x.id==='string'&&VARIANTS.some(v=>v.id===x.kind)).map(x=>({id:x.id.slice(0,90),kind:x.kind,profile:normalize(x.profile),referenceMode:x.referenceMode==='inspiration'?'inspiration':'strict',referenceId:typeof x.referenceId==='string'&&GALLERY.some(g=>g.id===x.referenceId)?x.referenceId:null,created:Number.isFinite(x.created)&&x.created>=0&&x.created<=8640000000000000?x.created:Date.now()})):[];}catch{return [];}}
