  const facePaths={round:'M18 30C15 10 65 10 62 30v19c0 22-44 22-44 0Z',oval:'M20 28C19 5 61 5 60 28v19c-2 24-38 24-40 0Z',square:'M18 27Q18 9 40 9t22 18v28q0 11-11 11H29Q18 66 18 55Z',heart:'M17 28Q17 9 40 9t23 19Q63 50 40 70 17 50 17 28Z',diamond:'M40 7 63 34 54 57 40 71 26 57 17 34Z',long:'M23 25Q23 5 40 5t17 20v29Q56 75 40 76 24 75 23 54Z'};
  function faceIllustration(id){return `<svg viewBox="0 0 80 85" aria-hidden="true"><path d="${facePaths[id]}" fill="#ecddcb" stroke="currentColor" stroke-width="1.2"/><path d="M28 35h4m16 0h4M35 54q5 4 10 0" fill="none" stroke="#a0856d" stroke-width="1.2" stroke-linecap="round"/></svg>`;}
