  function updateSelection(key){document.querySelectorAll(`[data-field="${key}"]`).forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.value===profile[key])));if(['eyes','hair'].includes(key))$(key+'-name').textContent=LABELS[key][profile[key]]||'עדיין לא נבחר';}
  function setTab(value,focus=false){tab=['profile','event','style'].includes(value)?value:'profile';const i=['profile','event','style'].indexOf(tab);document.querySelectorAll('[data-tab]').forEach(button=>{const active=button.dataset.tab===tab;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;$('panel-'+button.dataset.tab).hidden=!active;});$('previous-step').hidden=i===0;$('step-status').textContent=`שלב ${i+1} מתוך 3`;$('next-step').innerHTML=(i===0?'לבחירת אירוע':i===1?'לבחירת סגנון':'לראות את הלוקים שלי')+icon('arrow');if(focus)$('tab-'+tab).focus({preventScroll:true});}
